enum Animal = { Wolf, Rabbit, Goat, Parrot, Tortoise };

array[1..5] of var Animal: pen;

constraint pen[1] = Tortoise;
constraint pen[2] = Parrot;
constraint pen[3] = Goat;
constraint pen[4] = Rabbit \/ pen[5] = Rabbit; % Rabbit must be in pen 4 or 5
constraint pen[4] != Wolf /\ pen[5] != Wolf; % Wolf must be in pen 4 or 5
constraint pen[4] < pen[5]; % Rabbit must be in a lower-numbered pen than Wolf

constraint alldifferent(pen);

include "globals.mzn";

enum Animal = {Wolf, Rabbit, Goat, Parrot, Tortoise};

array[1..5] of var Animal: animalInPen;

constraint animalInPen[1] = Tortoise;
constraint animalInPen[2] = Parrot;
constraint animalInPen[3] = Goat;

constraint exists(i in 1..5)(animalInPen[i] = Rabbit \/ animalInPen[i] = Wolf) /\
    (forall(i in 1..4)(animalInPen[i] != animalInPen[i+1])) /\
    (forall(i in 1..5)(forall(j in 1..5)(if (animalInPen[i] = Wolf /\ animalInPen[j] = Rabbit) then i > j else true)));

